import content from './content.json';

// Generated by scripts/build_content.py — see content/*.tsv for the sources.
export const TOPICS = content.topics;
export const WORDS = content.words;
export const PHRASES = content.phrases;
export const POEM = content.poem;

export const topicById = (id) => TOPICS.find((t) => t.id === id);
export const wordsOf = (topic) => topic.words.map((id) => WORDS[id]);
export const audioUrl = (hash) => `${import.meta.env.BASE_URL}audio/${hash}.mp3`;

export const GENDER_NAME = { m: 'masculine', f: 'feminine', n: 'neuter' };
